  "name": "Rheumatology consultation",
  "category": "general",
  "setting": "opd",
  "fields": [
    {
      "key": "swollen_joints",
      "label": "Swollen joint count",
      "type": "number",
      "required": true
    },
    {
      "key": "morning_stiffness",
      "label": "Morning stiffness",
      "type": "select",
      "options": [
        "< 30 min",
        "30–60 min",
        "> 60 min"
      ]
    },
    {
      "key": "joints_involved",
      "label": "Joints involved",
      "type": "multiselect",
      "options": [
        "Hands",
        "Wrists",
        "Knees",
        "Feet"
      ]
    },
    {
      "key": "das28",
      "label": "DAS28 score",
      "type": "number"
    },
    {
      "key": "on_dmards",
      "label": "On DMARDs",
      "type": "boolean"
    }
  ]
}

